// Embedding (good for 1-to-few relationships)
{
  _id: ObjectId(),
  title: "MongoDB Basics",
  tags: ["nosql", "database"],  // embedded array
  author: { name: "Alice", email: "alice@ex.com" }  // embedded doc
}

// Referencing (good for 1-to-many)
{
  _id: ObjectId(),
  title: "Blog Post",
  authorId: ObjectId("...")  // reference to users collection
}
